using System.IdentityModel.Tokens.Jwt; using System.Security.Claims; using System.Text; using Microsoft.AspNetCore.Identity; using Microsoft.IdentityModel.Tokens; using PITF.Api.Models;
namespace PITF.Api.Services;
public sealed class JwtTokenService(IConfiguration config,UserManager<ApplicationUser> users){public async Task<string> CreateAsync(ApplicationUser user){var roles=await users.GetRolesAsync(user);var claims=new List<Claim>{new(JwtRegisteredClaimNames.Sub,user.Id.ToString()),new(JwtRegisteredClaimNames.Email,user.Email??""),new(ClaimTypes.Name,user.UserName??"")};claims.AddRange(roles.Select(x=>new Claim(ClaimTypes.Role,x)));var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(config["Jwt:Key"]??throw new InvalidOperationException("Jwt:Key missing")));return new JwtSecurityTokenHandler().WriteToken(new JwtSecurityToken(config["Jwt:Issuer"],config["Jwt:Audience"],claims,expires:DateTime.UtcNow.AddHours(8),signingCredentials:new SigningCredentials(key,SecurityAlgorithms.HmacSha256)));}}
